    transition_index = {
        level: index
        for index, level in enumerate(_GRADE_HISTORY_TRANSITION_LEVELS)
    }
    rows = []
    for s_index, scenario in enumerate(scenarios):
        levels = levels_by_scenario[s_index]
        valid = sum(level != "missing" for level in levels)
        transitions = [0] * 9
        count = 0
        changes = 0
